-- Campus des Tilleuls : 14 tables réellement utilisées, données fictives.
CREATE TABLE school_meta (id INT PRIMARY KEY, version INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE users (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, profile ENUM('Administration','Professeur','Élève','Parent') NOT NULL) ENGINE=InnoDB;
CREATE TABLE classes (id INT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE students (id INT PRIMARY KEY, user_id INT NOT NULL UNIQUE, class_id INT NOT NULL, guardian_id INT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(class_id) REFERENCES classes(id), FOREIGN KEY(guardian_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE courses (id INT PRIMARY KEY, teacher_id INT NOT NULL, title VARCHAR(100) NOT NULL, color CHAR(7) NOT NULL DEFAULT '#276759', FOREIGN KEY(teacher_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE enrollments (student_id INT NOT NULL, course_id INT NOT NULL, PRIMARY KEY(student_id,course_id), FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB;
CREATE TABLE lessons (id INT PRIMARY KEY, course_id INT NOT NULL, title VARCHAR(120) NOT NULL, starts_at DATETIME NOT NULL, room VARCHAR(40) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB;
CREATE TABLE attendance (lesson_id INT NOT NULL, student_id INT NOT NULL, status ENUM('présent','absent','retard') NOT NULL DEFAULT 'présent', PRIMARY KEY(lesson_id,student_id), FOREIGN KEY(lesson_id) REFERENCES lessons(id), FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE assignments (id INT PRIMARY KEY, course_id INT NOT NULL, title VARCHAR(120) NOT NULL, due_at DATE NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB;
CREATE TABLE grades (assignment_id INT NOT NULL, student_id INT NOT NULL, score DECIMAL(4,2) NULL, comment VARCHAR(240) NOT NULL DEFAULT '', version INT NOT NULL DEFAULT 1, PRIMARY KEY(assignment_id,student_id), FOREIGN KEY(assignment_id) REFERENCES assignments(id), FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE messages (id INT AUTO_INCREMENT PRIMARY KEY, sender_id INT NOT NULL, subject VARCHAR(120) NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(sender_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE message_recipients (message_id INT NOT NULL, user_id INT NOT NULL, read_at DATETIME NULL, PRIMARY KEY(message_id,user_id), FOREIGN KEY(message_id) REFERENCES messages(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE studio_notes (id INT AUTO_INCREMENT PRIMARY KEY, author_id INT NOT NULL, label VARCHAR(200) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE resources (id INT AUTO_INCREMENT PRIMARY KEY, course_id INT NOT NULL, author_id INT NOT NULL, title VARCHAR(120) NOT NULL, path VARCHAR(240) NOT NULL UNIQUE, mime VARCHAR(80) NOT NULL, bytes INT UNSIGNED NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB;
